import emotionStyled from '@emotion/styled';
import { styled } from '@hexa-ui/theme';

export const StyledInvestmentBreakdownWrapper = emotionStyled.div`
  display: flex;
  flex-direction: column;
  gap: 16px;
`;

export const StyledPageTitleRightContent = emotionStyled.div`
  display: flex;
  align-items: center;
  gap: 16px;
`;

export const StyledUsaAlertWrapper = emotionStyled.div`
  margin-bottom: 16px;
  margin-top: -16px;
`;

export const StyledNoDataYetContent = styled('div', {
  width: '100%',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
});

export const BrandsCellNoBorder = styled('div', {
  ".ag-center-cols-container .ag-cell[col-id='brands']": {
    borderTop: 'none !important',
    borderBottom: 'none !important',
  },
});
